/** How a key was pressed, as its param's value while it's down. A param set up with configKey() can tell a plain
click from a Shift+click and a Ctrl+click (⌘+click on a Mac); one set up with configButton() reads every press as
KEY_DOWN. */
enum KeyPress { KEY_UP, KEY_DOWN, KEY_SHIFT, KEY_CTRL };

template <class TQuantity = SwitchQuantity>
TQuantity* configKey(Module* m, int paramId, std::string name = "") {
	TQuantity* q = m->configButton<TQuantity>(paramId, name);
	q->maxValue = KEY_CTRL;
	return q;
}

/** Follows a key at control rate and says what it did: PRESS as it goes down, LONG_PRESS once it has been down
`longPress` seconds, and as it's let go, CLICK, or RELEASE if the module has already handled the press. */
struct KeyGesture {
	enum Event { NONE, PRESS, LONG_PRESS, CLICK, RELEASE };
	int press = KEY_UP;     // how it was last pressed
	float held = -1.f;      // seconds down, or -1 while up
	bool handled = false;   // the press did its job already, so letting go isn't a click

	Event process(float value, float dt, float longPress = 0.4f) {
		bool down = value > 0.f;
		if (down && held < 0.f) {
			press = (int) value;
			held = 0.f;
			handled = false;
			return PRESS;
		}
		if (!down && held >= 0.f) {
			held = -1.f;
			return handled ? RELEASE : CLICK;
		}
		if (down) {
			float before = held;
			held += dt;
			if (before < longPress && held >= longPress)
				return LONG_PRESS;
		}
		return NONE;
	}

	bool down() const {
		return held >= 0.f;
	}
};

/** A white symbol from res/components/symbols, `size` across, centred on `c`, in `color`. */
inline void drawSymbol(NVGcontext* vg, const std::shared_ptr<window::Svg>& symbol, math::Vec c, float size, NVGcolor color) {
	if (!symbol || !symbol->handle || color.a <= 0.f)
		return;
	math::Vec s = symbol->getSize();
	nvgSave(vg);
	nvgTranslate(vg, c.x - size / 2, c.y - size * s.y / s.x / 2);
	nvgScale(vg, size / s.x, size / s.x);
	nvgTint(vg, color);
	window::svgDraw(vg, symbol->handle);
	nvgRestore(vg);
}

inline std::shared_ptr<window::Svg> loadSymbol(const std::string& name) {
	return window::Svg::load(asset::plugin(pluginInstance, "res/components/symbols/" + name + ".svg"));
}


/** How the Sequencer's keys look, as its Appearance menu sets it: one style for every Sequencer, kept in Rack's
settings by plugin.cpp. */
namespace keys {

/** What shows round a held key: a halo or a wider reflection in its LED's colour, an outline, its ring lit, nothing,
or 2.1.4's grey fill. */
enum Glow { HALO, REFLECTION, OUTLINE, RIM, NO_GLOW, GREY_FILL, GLOWS };
/** The step and white keys' dot, the same size off and lit, or 2.1.4's, which grew when lit. */
enum Dot { DOT_17, DOT_22, DOT_26, DOT_CLASSIC, DOTS };
/** How an LED shows: on a solid dark window while lit; dark grey while off, with a dark edge while lit; on a dark
lens; or on 2.1.4's window, which fades in with the light. */
enum Led { TIGHT, DARK_GREY, LENS, WINDOW, LEDS };

struct Style {
	int glow = HALO;
	bool pressedIn = true;    // a press shades the key as if it sank into the panel
	int dot = DOT_22;
	int led = TIGHT;
};
extern Style style;

inline const char* const GLOW_NAMES[GLOWS] = {"Halo", "Reflection", "Outline", "Lit ring", "None", "Grey fill (2.1.4)"};
inline const char* const DOT_NAMES[DOTS] = {"1.7 mm", "2.2 mm", "2.6 mm", "1.7 mm, 3.1 mm lit (2.1.4)"};
inline const char* const LED_NAMES[LEDS] = {"Tight window", "Dark grey", "Dark lens", "Window (2.1.4)"};

inline const float RING = 0.648f;   // a key's printed ring's line (mm): res-src/opz.py's RING at the face's SCALE
inline const float EDGE = 0.3f;     // how far a symbol's keyline reaches (mm), as res-src/opz.py's EDGE
inline const NVGcolor PANEL = nvgRGB(0xec, 0xeb, 0xe8), PANEL_DARK = nvgRGB(0x2b, 0x2c, 0x2e);   // res-src/panelkit.py's
inline const NVGcolor INK = nvgRGB(0x3a, 0x3a, 0x3c), INK_DARK = nvgRGB(0xf2, 0xf1, 0xee);
inline const NVGcolor KEYLINE = nvgRGB(0x19, 0x19, 0x1b), LENS_FILL = nvgRGB(0x1e, 0x1f, 0x21), LENS_OFF = nvgRGB(0x55, 0x56, 0x5a);

/** The ink for a held key's neutral glow, which shows on the panel's theme. */
inline NVGcolor neutral() {
	return settings::preferDarkPanels ? INK_DARK : INK;
}

/** A ring of glow round (c), from r0 out to r1, fading out. */
inline void halo(NVGcontext* vg, math::Vec c, float r0, float r1, NVGcolor color, float alpha) {
	nvgBeginPath(vg);
	nvgCircle(vg, c.x, c.y, r1);
	nvgCircle(vg, c.x, c.y, r0);
	nvgPathWinding(vg, NVG_HOLE);
	nvgFillPaint(vg, nvgRadialGradient(vg, c.x, c.y, r0, r1, nvgTransRGBAf(color, alpha), nvgTransRGBAf(color, 0.f)));
	nvgFill(vg);
}

inline void ring(NVGcontext* vg, math::Vec c, float r, float width, NVGcolor color) {
	nvgBeginPath(vg);
	nvgCircle(vg, c.x, c.y, r);
	nvgStrokeColor(vg, color);
	nvgStrokeWidth(vg, width);
	nvgStroke(vg);
}

} // namespace keys


/** An OP-Z key's symbol and RGB LED: a dot, a number or an icon, drawn off in the panel theme's colours and lit in the
colour of its three lights, red, green and blue, as keys::style says. The symbols are res/components/symbols/<name>.svg,
white to be tinted, with <name>_edge.svg the same grown by keys::EDGE for a dark keyline; a dot is a circle. */
struct SymbolLight : app::ModuleLightWidget {
	std::shared_ptr<window::Svg> symbol, edge;   // null for a dot
	float radius = 0.f;     // the key's
	bool number = false;    // a black key's: a number on a solid disc

	void setSymbol(const std::string& name) {
		number = std::isdigit((unsigned char) name[0]);
		if (name != "dot") {
			symbol = loadSymbol(name);
			edge = loadSymbol(name + "_edge");
		}
	}

	static float dotSize(bool lit) {
		static const float sizes[] = {1.728f, 2.2f, 2.6f};
		int d = keys::style.dot;
		return mm2px(d == keys::DOT_CLASSIC ? (lit ? 3.11f : 1.728f) : sizes[d]);
	}

	/** How far the dark behind the symbol reaches: the lens, or the window behind it lit. */
	float windowRadius() const {
		if (symbol)
			return 0.64f * radius;
		float d = dotSize(true);
		switch (keys::style.led) {
			case keys::WINDOW: return keys::style.dot == keys::DOT_CLASSIC ? 0.64f * radius : 0.935f * d;
			case keys::LENS: return d / 2 + mm2px(0.6f);
			default: return d / 2 + mm2px(0.55f);
		}
	}

	/** The symbol's colour while its LED is off. A black key's number is knocked out of its disc, except where white
	light on the window would be no lighter than that. */
	NVGcolor offColor() const {
		bool dark = settings::preferDarkPanels;
		NVGcolor grey = nvgRGB(0x66, 0x66, 0x6a);
		switch (keys::style.led) {
			case keys::LENS: return keys::LENS_OFF;
			case keys::DARK_GREY: return dark ? nvgRGB(0x4c, 0x4d, 0x50) : number ? grey : keys::INK;
			case keys::TIGHT:
				if (number)
					return dark ? keys::PANEL_DARK : grey;
				[[fallthrough]];
			default: return number ? (dark ? keys::PANEL_DARK : keys::PANEL) : dark ? nvgRGB(0x87, 0x87, 0x85) : keys::INK;
		}
	}

	/** The symbol in `color`, as it is lit or off, or grown into its keyline. */
	void paint(NVGcontext* vg, NVGcolor color, bool lit, bool grown = false) const {
		math::Vec c = box.size.div(2);
		if (!symbol) {
			nvgBeginPath(vg);
			nvgCircle(vg, c.x, c.y, dotSize(lit) / 2 + (grown ? mm2px(keys::EDGE) : 0.f));
			nvgFillColor(vg, color);
			nvgFill(vg);
			return;
		}
		const std::shared_ptr<window::Svg>& svg = grown ? edge : symbol;
		if (!svg || !svg->handle)
			return;
		math::Vec size = svg->getSize();
		nvgSave(vg);
		nvgTranslate(vg, c.x - size.x / 2, c.y - size.y / 2);
		nvgTint(vg, color);
		window::svgDraw(vg, svg->handle);
		nvgRestore(vg);
	}

	/** The colour straight from the three lights, so mixes keep their hue rather than being blended by brightness. */
	void step() override {
		color = nvgRGBAf(0.f, 0.f, 0.f, 0.f);
		if (module && !module->isBypassed() && firstLightId >= 0 && firstLightId + 3 <= (int) module->lights.size()) {
			float c[3];
			for (int i = 0; i < 3; i++) {
				float b = module->lights[firstLightId + i].getBrightness();
				c[i] = std::isfinite(b) ? clamp(b, 0.f, 1.f) : 0.f;
			}
			float m = std::max({c[0], c[1], c[2]});
			if (m > 0.f)
				color = nvgRGBAf(c[0] / m, c[1] / m, c[2] / m, std::sqrt(m));
		}
		widget::Widget::step();
	}

	/** Off, on the panel: the lens, if any, and the symbol. */
	void draw(const DrawArgs& args) override {
		if (keys::style.led == keys::LENS) {
			nvgBeginPath(args.vg);
			nvgCircle(args.vg, box.size.x / 2, box.size.y / 2, windowRadius());
			nvgFillColor(args.vg, keys::LENS_FILL);
			nvgFill(args.vg);
		}
		paint(args.vg, offColor(), false);
		Widget::draw(args);
	}

	/** Lit, over the panel: the dark it sits on, a soft glow, and the symbol in its colour, as bright as the light. */
	void drawLayer(const DrawArgs& args, int layer) override {
		if (layer == 1 && color.a > 0.f) {
			NVGcontext* vg = args.vg;
			math::Vec c = box.size.div(2);
			int led = keys::style.led;
			if (led == keys::WINDOW || led == keys::TIGHT) {
				NVGcolor shade = settings::preferDarkPanels ? nvgRGB(0x14, 0x15, 0x16) : keys::INK;
				nvgBeginPath(vg);
				nvgCircle(vg, c.x, c.y, windowRadius());
				nvgFillColor(vg, led == keys::WINDOW ? nvgTransRGBAf(shade, color.a) : shade);
				nvgFill(vg);
			}
			else if (led == keys::DARK_GREY) {
				paint(vg, keys::KEYLINE, true, true);
				paint(vg, offColor(), true);
			}
			if (settings::haloBrightness > 0.f) {
				float r = 1.4f * radius;
				nvgBeginPath(vg);
				nvgCircle(vg, c.x, c.y, r);
				NVGcolor glow = nvgTransRGBAf(color, 0.35f * color.a * settings::haloBrightness);
				nvgFillPaint(vg, nvgRadialGradient(vg, c.x, c.y, 0.f, r, glow, nvgTransRGBAf(color, 0.f)));
				nvgFill(vg);
			}
			paint(vg, color, true);
		}
		Widget::drawLayer(args, layer);
	}
};

/** A momentary key as the OP-Z's work: a press sets the param to how it was pressed (see KeyPress), and it springs
back on release, but not before the module has had a frame to see it. It draws nothing; RoundKey and the
Sequencer's display keys do, with push() and hold() for how far in and how long it's been held. */
struct PressKey : app::ParamWidget {
	int frames = -1;        // frames since the press, or -1 while up
	bool released = false;
	bool hovered = false;
	double downAt = -1.0;   // when it went down (system::getTime()), or -1 while it's up
	double upAt = -1.0;     // when it was last let go
	float heldAtUp = 0.f;   // hold() as it was let go, to fade out from

	void onEnter(const EnterEvent& e) override {
		hovered = true;
		ParamWidget::onEnter(e);
	}
	void onLeave(const LeaveEvent& e) override {
		hovered = false;
		ParamWidget::onLeave(e);
	}

	bool pressed() {
		engine::ParamQuantity* pq = getParamQuantity();
		return pq && pq->getValue() > 0.f;
	}

	/** How far in the key is pushed: all the way while it's down, then out over 0.15 s, so a quick click shows too. */
	float push() const {
		if (downAt >= 0.0)
			return 1.f;
		return upAt < 0.0 ? 0.f : clamp(1.f - float(system::getTime() - upAt) / 0.15f, 0.f, 1.f);
	}

	/** How much the key glows as held: from 0.1 s down it grows, to full at 0.4 s, when a long press counts, and it
	fades over 0.2 s once let go. */
	float hold() const {
		if (downAt >= 0.0)
			return clamp(float(system::getTime() - downAt - 0.1) / 0.3f, 0.f, 1.f);
		return upAt < 0.0 ? 0.f : heldAtUp * clamp(1.f - float(system::getTime() - upAt) / 0.2f, 0.f, 1.f);
	}

	void initParamQuantity() override {
		ParamWidget::initParamQuantity();
		if (engine::ParamQuantity* pq = getParamQuantity()) {
			pq->snapEnabled = true;
			pq->smoothEnabled = false;
			pq->resetEnabled = false;
			pq->randomizeEnabled = false;
		}
	}

	void onButton(const ButtonEvent& e) override {
		ParamWidget::onButton(e);
		// Rack's params take only plain clicks; take Shift and Ctrl clicks too, rather than selecting the module.
		if (e.action == GLFW_PRESS && e.button == GLFW_MOUSE_BUTTON_LEFT)
			e.consume(this);
	}
	void onDoubleClick(const DoubleClickEvent& e) override {}

	void onDragStart(const DragStartEvent& e) override {
		engine::ParamQuantity* pq = getParamQuantity();
		if (e.button != GLFW_MOUSE_BUTTON_LEFT || !pq)
			return;
		int mods = APP->window->getMods() & RACK_MOD_MASK;
		pq->setValue(mods == GLFW_MOD_SHIFT ? KEY_SHIFT : mods == RACK_MOD_CTRL ? KEY_CTRL : KEY_DOWN);
		frames = 0;
		released = false;
	}
	void onDragEnd(const DragEndEvent& e) override {
		if (e.button == GLFW_MOUSE_BUTTON_LEFT)
			released = true;
	}

	void step() override {
		if (frames >= 0 && ++frames > 1 && released) {
			if (engine::ParamQuantity* pq = getParamQuantity())
				pq->setMin();
			frames = -1;
		}
		// Down however it got there: the mouse, or a MIDI map.
		bool down = pressed();
		if (down && downAt < 0.0)
			downAt = system::getTime();
		else if (!down && downAt >= 0.0) {
			heldAtUp = hold();
			upAt = system::getTime();
			downAt = -1.0;
		}
		ParamWidget::step();
	}
};

/** An OP-Z key: round, with an RGB LED in its middle that lights up its symbol. Its ring is printed on the panel; it
draws the symbol, how far it's pushed in and its glow while held, as keys::style says. Pass createLightParam the first
of its three light ids, then place it with setRing. */
struct RoundKey : PressKey {
	SymbolLight* light = new SymbolLight;
	float radius = 0.f;     // the printed ring's, to its outer edge

	RoundKey() {
		addChild(light);
	}

	/** Puts the key over its printed ring, taking clicks a little way outside it too. */
	void setRing(math::Rect ring, const std::string& symbol) {
		box = ring.grow(mm2px(math::Vec(1.1f, 1.1f)));
		radius = ring.size.x / 2;
		light->box.size = box.size;
		light->radius = radius;
		light->setSymbol(symbol);
	}
	app::ModuleLightWidget* getLight() {
		return light;
	}

	/** The symbol, then the shading of a press, darkest along the top inside the ring, or 2.1.4's grey fill. */
	void draw(const DrawArgs& args) override {
		ParamWidget::draw(args);
		NVGcontext* vg = args.vg;
		math::Vec c = box.size.div(2);
		bool dark = settings::preferDarkPanels;
		float p = push();
		if (keys::style.pressedIn && p > 0.f) {
			float inner = light->number ? radius : radius - mm2px(keys::RING), drop = mm2px(1.3f);
			nvgBeginPath(vg);
			nvgCircle(vg, c.x, c.y, inner);
			nvgFillPaint(vg, nvgRadialGradient(vg, c.x, c.y + drop, inner - mm2px(2.f), inner + drop, nvgRGBAf(0.f, 0.f, 0.f, 0.f),
				nvgRGBAf(0.f, 0.f, 0.f, p * (dark ? 0.6f : 0.36f))));
			nvgFill(vg);
		}
		if (keys::style.glow == keys::GREY_FILL && pressed()) {
			nvgBeginPath(vg);
			nvgCircle(vg, c.x, c.y, radius);
			nvgFillColor(vg, dark ? nvgRGBAf(1.f, 1.f, 1.f, 0.2f) : nvgRGBAf(0.f, 0.f, 0.f, 0.18f));
			nvgFill(vg);
		}
	}

	/** The glow of a held key, under its light: in its LED's colour, or a neutral one while that's off. On the light
	panel a pale LED's glow wouldn't show, so white takes the neutral too. */
	void drawLayer(const DrawArgs& args, int layer) override {
		float h = layer == 1 ? hold() : 0.f;
		if (h > 0.f) {
			NVGcontext* vg = args.vg;
			math::Vec c = box.size.div(2);
			bool dark = settings::preferDarkPanels;
			NVGcolor led = light->color;
			bool lit = led.a > 0.f && (dark || 0.2126f * led.r + 0.7152f * led.g + 0.0722f * led.b <= 0.8f);
			NVGcolor color = lit ? nvgTransRGBAf(led, 1.f) : keys::neutral();
			switch (keys::style.glow) {
				case keys::HALO:
					keys::halo(vg, c, radius + mm2px(0.1f), radius + mm2px(2.4f), color, h * (lit ? 0.85f : dark ? 0.5f : 0.38f));
					break;
				case keys::REFLECTION:
					keys::halo(vg, c, radius - mm2px(0.2f), radius + mm2px(5.5f), color, h * (lit ? 0.42f : dark ? 0.26f : 0.2f));
					break;
				case keys::OUTLINE:
					keys::ring(vg, c, radius + mm2px(0.8f), mm2px(0.45f), nvgTransRGBAf(keys::neutral(), h));
					break;
				case keys::RIM:
					keys::ring(vg, c, radius - mm2px(light->number ? 0.4f : keys::RING / 2), mm2px(1.8f * keys::RING), nvgTransRGBAf(color, h));
					break;
			}
		}
		PressKey::drawLayer(args, layer);
	}
};

/** An invisible momentary button, for making printed artwork clickable. */
struct HotSpot : app::Switch {
	HotSpot() {
		momentary = true;
	}
};



/** A seven-segment LED display's characters, drawn as pointed bars and slanted a little. A mask's bits are the
segments from the top clockwise, then the middle one. */
struct SevenSegment {
	static constexpr uint8_t DIGITS[10] = {0x3f, 0x06, 0x5b, 0x4f, 0x66, 0x6d, 0x7d, 0x07, 0x7f, 0x6f};

	/** Digits, '-', '_', ' ', and the letters a seven-segment display can make. */
	static uint8_t mask(char c) {
		if (c >= '0' && c <= '9')
			return DIGITS[c - '0'];
		switch (c) {
			case 'A': return 0x77; case 'b': return 0x7c; case 'C': return 0x39; case 'c': return 0x58;
			case 'd': return 0x5e; case 'E': return 0x79; case 'F': return 0x71; case 'G': return 0x3d;
			case 'H': return 0x76; case 'h': return 0x74; case 'i': return 0x10; case 'J': return 0x1e;
			case 'L': return 0x38; case 'n': return 0x54; case 'o': return 0x5c; case 'P': return 0x73;
			case 'r': return 0x50; case 'S': return 0x6d; case 't': return 0x78; case 'U': return 0x3e;
			case 'u': return 0x1c; case 'y': return 0x6e; case '-': return 0x40; case '_': return 0x08;
			default: return 0;
		}
	}

	/** A segment from p to q, pointed at both ends and pulled back from them a little. */
	static void segment(NVGcontext* vg, math::Vec p, math::Vec q, float r) {
		math::Vec u = q.minus(p).normalize(), n(-u.y, u.x);
		float gap = 0.25f * r;
		nvgMoveTo(vg, VEC_ARGS(p.plus(u.mult(gap))));
		nvgLineTo(vg, VEC_ARGS(p.plus(u.mult(gap + r)).plus(n.mult(r))));
		nvgLineTo(vg, VEC_ARGS(q.minus(u.mult(gap + r)).plus(n.mult(r))));
		nvgLineTo(vg, VEC_ARGS(q.minus(u.mult(gap))));
		nvgLineTo(vg, VEC_ARGS(q.minus(u.mult(gap + r)).minus(n.mult(r))));
		nvgLineTo(vg, VEC_ARGS(p.plus(u.mult(gap + r)).minus(n.mult(r))));
		nvgClosePath(vg);
	}

	/** `text`'s lit segments, or for the ghosts behind them its unlit ones, spread across `box`. */
	static void draw(NVGcontext* vg, math::Rect box, const std::string& text, bool lit, NVGcolor color) {
		int n = std::max((int) text.size(), 1);
		float h = box.size.y, w = 0.5f * h, r = 0.06f * h;
		float gap = n > 1 ? (box.size.x - n * w) / (n - 1) : 0.f, left = n > 1 ? box.pos.x : box.pos.x + (box.size.x - w) / 2;
		nvgSave(vg);
		nvgTranslate(vg, 0, box.pos.y + h / 2);
		nvgSkewX(vg, -0.1f);
		nvgTranslate(vg, 0, -(box.pos.y + h / 2));
		nvgBeginPath(vg);
		for (int d = 0; d < (int) text.size(); d++) {
			uint8_t m = mask(text[d]);
			float x = left + d * (w + gap), y = box.pos.y;
			const math::Vec corners[6] = {{x, y}, {x + w, y}, {x + w, y + h / 2}, {x + w, y + h}, {x, y + h}, {x, y + h / 2}};
			const int ends[7][2] = {{0, 1}, {1, 2}, {2, 3}, {3, 4}, {5, 4}, {0, 5}, {5, 2}};
			for (int s = 0; s < 7; s++)
				if (bool(m & (1 << s)) == lit)
					segment(vg, corners[ends[s][0]], corners[ends[s][1]], r);
		}
		nvgFillColor(vg, color);
		nvgFill(vg);
		nvgRestore(vg);
	}
};
